"""
Ajoute au warehouse (data/warehouse.seed.json) le registre consolidé des
dépenses sociales et environnementales (Exigence ITIE 6.1), à partir du
fichier fourni par l'utilisateur « ITIE_RDC_Depenses_sociales_environnementales_6.1
1.xlsx » — une compilation déjà préparée, ligne par projet, des Annexes 33 à
36 du Rapport ITIE-RDC 2022 et des Annexes 38 à 41 du Rapport ITIE-RDC 2023
(dépenses sociales obligatoires/volontaires du secteur minier, dépenses
sociales obligatoires du secteur pétrolier, dépenses environnementales
obligatoires du secteur minier).

Objectif de l'utilisateur : une section « très claire et simple » pour
l'Exigence 6.1 — ce script ajoute donc, au thème existant `depenses_sociales`
(qui contient déjà toutes les annexes brutes 2022/2023, non touchées ici) :
  1) une vue d'ensemble (1 ligne, les grands totaux),
  2) une synthèse annuelle par catégorie (8 lignes, déjà agrégée dans le
     fichier source),
  3) le registre détaillé, projet par projet (902 lignes, 23 colonnes),
     reproduit tel quel.

Principe (« ne rien cacher, toutes ces données sont publiques ») : les 902
lignes de détail et leurs valeurs manquantes ou atypiques sont reproduites
exactement telles que fournies dans le fichier Excel source ; aucune valeur
n'est complétée, recalculée ou corrigée (voir meta.qualite ci-dessous pour
les anomalies identifiées dans le fichier source lui-même).
"""
from __future__ import annotations

import json
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent
WAREHOUSE_PATH = BASE_DIR / "data" / "warehouse.seed.json"

SOURCE_XLSX = (
    "« ITIE_RDC_Depenses_sociales_environnementales_6.1 1.xlsx », fourni "
    "directement par l'utilisateur (2026-09-24) — registre consolidé, "
    "ligne par projet, des Annexes 33 à 36 du Rapport ITIE-RDC 2022 et des "
    "Annexes 38 à 41 du Rapport ITIE-RDC 2023, au titre de l'Exigence ITIE "
    "6.1 (dépenses sociales et paiements environnementaux)."
)

THEME_KEY = "depenses_sociales"
THEME_LABEL = "Dépenses sociales et environnementales"

COMMON_META = dict(
    theme=THEME_KEY,
    theme_label=THEME_LABEL,
    source=SOURCE_XLSX,
    periode="2022-2023",
    devise="USD",
)

DATASETS: dict = {}


def add(name, label, cat, desc, cols, types, rows, **meta_over):
    meta = dict(COMMON_META)
    meta.update(meta_over)
    DATASETS[name] = dict(label=label, cat=cat, desc=desc, cols=cols, types=types, rows=rows, meta=meta)


